"""Generated by func2vec.generate_cluster.
Intent: k=unknown dataset_size=small data_kind=tabular structure=partition
Picked algorithm: sklearn.cluster.DBSCAN
Preprocessing (embedding-picked where applicable): ['sklearn.preprocessing.MinMaxScaler']
Evaluation (embedding-ranked): ['sklearn.metrics.homogeneity_score', 'sklearn.metrics.davies_bouldin_score', 'sklearn.metrics.completeness_score']
"""

import numpy as np
from sklearn.datasets import make_blobs
from sklearn.preprocessing import MinMaxScaler
from sklearn.cluster import DBSCAN
from sklearn.metrics import homogeneity_score
from sklearn.metrics import davies_bouldin_score
from sklearn.metrics import completeness_score


def load_data():
    X, y = make_blobs(n_samples=1500, centers=4, n_features=20,
                      cluster_std=1.2, random_state=42)
    return X, y


def build_pipeline():
    steps = []
    steps.append(MinMaxScaler())
    steps.append(DBSCAN(eps=0.5, min_samples=5))
    return steps


def run(X, y=None):
    steps = build_pipeline()
    Xt = X
    for step in steps[:-1]:
        Xt = step.fit_transform(Xt)
    clusterer = steps[-1]
    if hasattr(clusterer, 'fit_predict'):
        labels = clusterer.fit_predict(Xt)
    else:
        clusterer.fit(Xt)
        labels = clusterer.labels_

    scoreable = labels[labels != -1] if -1 in np.unique(labels) else labels
    Xs = Xt[labels != -1] if -1 in np.unique(labels) else Xt
    n_clusters = len(set(scoreable))
    print(f'algorithm    : {clusterer.__class__.__name__}')
    print(f'n_clusters   : {n_clusters}')
    if n_clusters >= 2:
        if y is not None:
            print(f'homogeneity_score       : {homogeneity_score(y, labels):.4f}')
        print(f'davies_bouldin_score    : {davies_bouldin_score(Xs, scoreable):.4f}')
        if y is not None:
            print(f'completeness_score      : {completeness_score(y, labels):.4f}')
    else:
        print('too few clusters formed to score')
    return labels


if __name__ == '__main__':
    X, y = load_data()
    run(X, y)
